struct po
{
  float data[16];
};

class entity
{
public:
  void set_visible(bool);
  void update_region(bool force = true);
  void set_rel_po(const po&);
};

__asm__(".equ set_visible__6entityb,0x00138E00");
__asm__(".equ update_region__6entityb,0x00134E20");

class beach_object
{
  void* vtable;

public:
  float spawn_time;
  int timer_type;
  int times_spawned;
  int spawned;
  int smashable;
  int active;
  int never_despawn;
  int physical;

protected:
  entity* my_entity;
  int spawn_count;
};

class beach_billboard : public beach_object
{
  char padding0[20];
  po my_initial_po;
  int rotate;
  float my_age;
  float my_life;

public:
  void spawn();
};

void beach_billboard::spawn ()
{
  if (times_spawned == spawn_count)
    return;

  my_entity->set_visible (true);
  my_entity->update_region ();

  //my_entity->set_rel_po (po_identity_matrix);
  my_entity->set_rel_po(my_initial_po);

  my_age = 0;
  spawned = true;
  times_spawned++;
}
